import unittest

class TestFizzBuzzFunction(unittest.TestCase):
    def test_basic_fizzbuzz(self):
        """Test the function with basic input (n = 5)."""
        self.assertEqual(solution(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_fizzbuzz_with_fifteen(self):
        """Test the function with n = 15 to cover more cases."""
        self.assertEqual(solution(15), ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz", "11", "Fizz", "13", "14", "FizzBuzz"])

    def test_fizzbuzz_with_single(self):
        """Test the function with n = 1 to check boundary condition."""
        self.assertEqual(solution(1), ["1"])

    def test_fizzbuzz_with_n_equal_to hundred(self):
        """Test the function with n = 100 to check upper boundary condition."""
        self.assertEqual(len(solution(100)), 100)

    def test_fizzbuzz_with_zero(self):
        """Test the function with n = 0 to check invalid input."""
        with self.assertRaises(ValueError):
            solution(0)

    def test_fizzbuzz_with_negative_number(self):
        """Test the function with n = -5 to check invalid input."""
        with self.assertRaises(ValueError):
            solution(-5)

    def test_fizzbuzz_with_non_integer(self):
        """Test the function with n = 3.5 to check invalid input type."""
        with self.assertRaises(TypeError):
            solution(3.5)

if __name__ == '__main__':
    unittest.main()

