class TestFizzBuzzFunction(unittest.TestCase):
    def test_basic_fizzbuzz(self):
        """Test the function with a basic input of n = 5."""
        self.assertEqual(solution(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_fizzbuzz_with_fizz(self):
        """Test the function with a multiple of 3."""
        self.assertEqual(solution(3), ["1", "2", "Fizz"])

    def test_fizzbuzz_with_buzz(self):
        """Test the function with a multiple of 5."""
        self.assertEqual(solution(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_fizzbuzz_with_fizzbuzz(self):
        """Test the function with a multiple of both 3 and 5."""
        self.assertEqual(solution(15), ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz", "11", "Fizz", "13", "14", "FizzBuzz"])

    def test_fizzbuzz_with_n_equals_1(self):
        """Test the function with n = 1."""
        self.assertEqual(solution(1), ["1"])

    def test_fizzbuzz_with_n_equals_100(self):
        """Test the function with the maximum input n = 100."""
        result = solution(100)
        self.assertEqual(result[2], "Fizz")
        self.assertEqual(result[4], "Buzz")
        self.assertEqual(result[14], "FizzBuzz")

    def test_fizzbuzz_with_invalid_input(self):
        """Test the function with an invalid input (n < 1)."""
        with self.assertRaises(ValueError):
            solution(0)

    def test_fizzbuzz_with_non_integer_input(self):
        """Test the function with a non-integer input."""
        with self.assertRaises(TypeError):
            solution("5")

