class TestCountVowelsFunction(unittest.TestCase):
    def test_basic_vowels(self):
        """Test the function with a string containing basic vowels."""
        self.assertEqual(solution("Hello, World!"), 3)

    def test_all_vowels(self):
        """Test the function with a string containing all vowels."""
        self.assertEqual(solution("aeiouAEIOU"), 10)

    def test_no_vowels(self):
        """Test the function with a string containing no vowels."""
        self.assertEqual(solution("bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"), 0)

    def test_empty_string(self):
        """Test the function with an empty string."""
        self.assertEqual(solution(""), 0)

    def test_single_vowel(self):
        """Test the function with a string containing a single vowel."""
        self.assertEqual(solution("a"), 1)

    def test_large_string(self):
        """Test the function with a large string containing multiple vowels."""
        large_string = "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua."
        self.assertEqual(solution(large_string), 43)

    def test_punctuation_and_spaces(self):
        """Test the function with a string containing punctuation and spaces."""
        self.assertEqual(solution("!@#$%^&*()_+-={}:<>?,./"), 0)

    def test_numbers(self):
        """Test the function with a string containing numbers."""
        self.assertEqual(solution("1234567890"), 0)

