class TestSumOfEvenNumbersFunction(unittest.TestCase):
    def test_basic_even_sum(self):
        """Test the function with a basic case where n is even."""
        self.assertEqual(solution(10), 30)

    def test_basic_odd_sum(self):
        """Test the function with a basic case where n is odd."""
        self.assertEqual(solution(5), 6)

    def test_smallest_input(self):
        """Test the function with the smallest possible input (n=1)."""
        self.assertEqual(solution(1), 0)

    def test_largest_input(self):
        """Test the function with the largest possible input (n=1000)."""
        self.assertEqual(solution(1000), 250500)

    def test_single_even_number(self):
        """Test the function with a single even number (n=2)."""
        self.assertEqual(solution(2), 2)

    def test_single_odd_number(self):
        """Test the function with a single odd number (n=1)."""
        self.assertEqual(solution(1), 0)

    def test_even_number_in_middle(self):
        """Test the function with an even number in the middle of the range (n=7)."""
        self.assertEqual(solution(7), 12)

    def test_large_even_number(self):
        """Test the function with a large even number (n=100)."""
        self.assertEqual(solution(100), 2550)

    def test_stress_test(self):
        """Perform a stress test with multiple iterations."""
        for _ in range(100):
            n = 1000  # max input value
            result = solution(n)
            self.assertEqual(result, 250500)

    def test_input_as_string(self):
        """Test the function with input as a string."""
        with self.assertRaises(TypeError):
            solution("10")

    def test_input_as_float(self):
        """Test the function with input as a float."""
        with self.assertRaises(TypeError):
            solution(10.5)

    def test_input_below_range(self):
        """Test the function with input below the specified range (n=0)."""
        with self.assertRaises(ValueError):
            solution(0)

    def test_input_above_range(self):
        """Test the function with input above the specified range (n=1001)."""
        with self.assertRaises(ValueError):
            solution(1001)

if __name__ == '__main__':
    unittest.main()

