def solution(score: int) -> str:
    """
    This function calculates the letter grade based on the given score.

    Args:
    score (int): The score of a student.

    Returns:
    str: The corresponding letter grade or "Invalid score" if the score is outside the range of 0 to 100.
    """

    # Check if the score is within the valid range
    if score < 0 or score > 100:
        return "Invalid score"

    # Calculate the grade based on the score
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    elif score >= 60:
        return "D"
    else:
        return "F"

