    This function calculates the factorial of a given non-negative integer n.

    Args:
    n (int): A non-negative integer (0 <= n <= 12)

    Returns:
    int: The factorial of n
    """

    # Base case: The factorial of 0 is defined to be 1
    if n == 0:
        return 1

    # Recursive case: n! = n * (n-1)!
    else:
        # Check if n is within the given constraints
        if 0 <= n <= 12:
            return n * solution(n-1)
        else:
            # If n is not within the constraints, raise a ValueError
            raise ValueError("Input must be a non-negative integer and not exceed 12.")

