def solution(s: str) -> int:
    """
    Returns the index of the first non-repeating character in a given string.

    Args:
    s (str): A string consisting of lowercase English letters.

    Returns:
    int: The index of the first unique character, or -1 if there are no unique characters.
    """

    # Create a dictionary to store the frequency of each character
    char_freq = {}

    # First pass: count the frequency of each character
    for char in s:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # Second pass: find the first character with a frequency of 1
    for index, char in enumerate(s):
        if char_freq[char] == 1:
            return index

    # If no unique character is found, return -1
    return -1

