def solution(nums, k):
    left = 0
    zero_count = 0
    max_length = 0

    for right in range(len(nums)):
        if nums[right] == 0:
            zero_count += 1

        while zero_count > k:
            if nums[left] == 0:
                zero_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

def solution(nums):
    """
    This function returns the length of the longest strictly increasing subsequence (LIS) in a given integer array.

    Args:
    nums (list): A list of integers.

    Returns:
    int: The length of the longest increasing subsequence.

    """
    if not nums:  
        return 0

    tails = [nums[0]]

    for num in nums[1:]:
        if num > tails[-1]:
            tails.append(num)
        else:
            left, right = 0, len(tails) - 1
            while left < right: 
                mid = (left + right) // 2
                if tails[mid] < num:
                    left = mid + 1
                else:
                    right = mid 
            tails[left] = num

    return len(tails)

