def solution(s: str) -> bool:
    """
    This function validates whether a given string of parentheses is valid.
    A string of parentheses is considered valid if every opening parenthesis has a corresponding closing parenthesis and the parentheses are closed in the correct order.

    Args:
    s (str): A string consisting of just the characters '(' and ')'.

    Returns:
    bool: True if the string of parentheses is valid, False otherwise.
    """

    def recursive_validator(s: str, stack: list) -> bool:
        # Base case: If the string is empty, the parentheses are valid if and only if the stack is empty.
        if not s:
            return not stack

        # If the current character is an opening parenthesis, push it onto the stack and recurse.
        if s[0] == '(':
            return recursive_validator(s[1:], stack + ['('])

        # If the current character is a closing parenthesis, check if the stack is empty.
        # If the stack is empty, there's no matching opening parenthesis, so return False.
        # Otherwise, pop the opening parenthesis from the stack and recurse.
        elif s[0] == ')':
            if not stack:
                return False
            else:
                return recursive_validator(s[1:], stack[:-1])

        # If the current character is neither '(' nor ')', the input string is invalid.
        else:
            return False

    # Call the recursive helper function with an empty stack.
    return recursive_validator(s, [])

