def solution(s: str) -> bool:
    """
    This function validates whether a given string of parentheses is valid.
    A string of parentheses is considered valid if every opening parenthesis has a corresponding closing parenthesis and the parentheses are closed in the correct order.

    Args:
    s (str): A string consisting of just the characters '(' and ')'.

    Returns:
    bool: True if the string of parentheses is valid, False otherwise.
    """

    def recursive_validator(index: int, count: int) -> bool:
        # Base case: If the index is equal to the length of the string, the parentheses are valid if and only if the count is 0.
        if index == len(s):
            return count == 0

        # If the current character is an opening parenthesis, recurse with the count incremented.
        if s[index] == '(':
            return recursive_validator(index + 1, count + 1)

        # If the current character is a closing parenthesis, check if the count is 0.
        # If the count is 0, there's no matching opening parenthesis, so return False.
        # Otherwise, recurse with the count decremented.
        elif s[index] == ')':
            if count == 0:
                return False
            else:
                return recursive_validator(index + 1, count - 1)

        # If the current character is neither '(' nor ')', the input string is invalid.
        else:
            return False

    # Call the recursive helper function with an initial index and count.
    return recursive_validator(0, 0)

