    """
    This function validates whether a given string of parentheses is valid.
    A string of parentheses is considered valid if every opening parenthesis has a corresponding closing parenthesis and the parentheses are closed in the correct order.

    Args:
    s (str): A string consisting of just the characters '(' and ')'.

    Returns:
    bool: True if the string of parentheses is valid, False otherwise.
    """

    def recursive_validator(s: str) -> bool:
        # Base case: If the string is empty, the parentheses are valid.
        if not s:
            return True

        # If the string starts with a closing parenthesis, the parentheses are invalid.
        if s[0] == ')':
            return False

        # Find the corresponding closing parenthesis.
        for i in range(1, len(s)):
            if s[i] == ')':
                # Recurse on the substring after the closing parenthesis.
                return recursive_validator(s[i+1:])

        # If no corresponding closing parenthesis is found, the parentheses are invalid.
        return False

    # Call the recursive helper function.
    return recursive_validator(s)

