def solution(structure):
    """
    Evaluates a nested structure of integers and lists, applying specific conditions to sum or subtract integers based on their parity and depth.

    Args:
    structure: A nested list containing integers and other nested lists.

    Returns:
    An integer representing the total evaluation according to the conditions specified.
    """
    def recursive_eval(structure, depth):
        # Initialize the total sum to 0
        total = 0
        # Iterate over each element in the structure
        for element in structure:
            # If the element is a list, recursively evaluate it with increased depth
            if isinstance(element, list):
                total += recursive_eval(element, depth + 1)
            # If the element is an integer
            elif isinstance(element, int):
                # If the integer is even, add it to the total
                if element % 2 == 0:
                    total += element
                # If the integer is odd, check the depth
                else:
                    # If the depth is odd, subtract the integer from the total
                    if depth % 2 != 0:
                        total -= element
                    # If the depth is even, add the integer to the total
                    else:
                        total += element
        # Return the total sum
        return total

    # If the structure is an integer, directly evaluate it with a depth of 0
    if isinstance(structure, int):
        if structure % 2 == 0:
            return structure
        else:
            return structure if depth % 2 == 0 else -structure
    # If the structure is a list, start the recursive evaluation with the initial structure and a depth of 0
