def solution(nums, target):
    """
    Searches for a target integer in a rotated sorted array.

    Args:
    - nums: A list of integers (1 <= nums.length <= 10^5) which is a rotated version of a sorted array.
    - target: An integer (-10^9 <= target <= 10^9)

    Returns:
    - An integer representing the index of `target` in `nums`, or -1 if `target` is not found.

    Raises:
    - ValueError: If the input array contains non-integer elements.
    """
    # Check if all elements in nums are integers
    if not all(isinstance(num, int) for num in nums):
        raise ValueError("Input array contains non-integer elements")

    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid

        # Check if left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # If left half is not sorted, right half must be sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

