def solution(s: str) -> int:
    """
    This function returns the minimum number of substrings that can be formed 
    such that each substring is a palindrome.

    Args:
    s (str): A string of lowercase letters.

    Returns:
    int: The minimum number of palindromic substrings.
    """

    n = len(s)
    dp = [[False] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = True
        for j in range(i + 1, n):
            if s[i] == s[j] and (j - i == 1 or dp[i + 1][j - 1]):
                dp[i][j] = True

    memo = {}
    def recursive_decomposition(i):
        if i in memo:
            return memo[i]
        if i == n:
            return 0
        min_substrings = float('inf')
        for j in range(i, n):
            if dp[i][j]:
                min_substrings = min(min_substrings, 1 + recursive_decomposition(j + 1))
        memo[i] = min_substrings
        return min_substrings

    return recursive_decomposition(0)

