def solution(s: str) -> int:
    n = len(s)
    dp = [[False]*n for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if length == 2:
                dp[i][j] = s[i] == s[j]
            else:
                dp[i][j] = s[i] == s[j] and dp[i+1][j-1]

    memo = {}
    def recurse(i):
        if i in memo:
            return memo[i]
        if i == n:
            return 0
        ans = float('inf')
        for j in range(i, n):
            if dp[i][j]:
                ans = min(ans, 1 + recurse(j+1))
        memo[i] = ans
        return ans

    return recurse(0)

