def solution(numbers, operations):
    """
    Applies a list of operations to a list of numbers.

    Args:
        numbers (list): A list of integers.
        operations (list): A list of operations as strings.

    Returns:
        list: A list of results after applying operations or "Operation not possible" if an error occurred.
    """
    result = []

    # Iterate over the numbers and operations
    for num, op in zip(numbers, operations):
        if op == "double":
            result.append(num * 2)
        elif op == "increment":
            result.append(num + 1)
        elif op == "decrement":
            # Check for error condition before decrementing
            if num <= 0:
                if num == 0:
                    result.append("Operation not possible")
                else:
                    result.append(num - 1)
            else:
                result.append(num - 1)

    return result

