def solution(nums, target):
    """
    Searches for a target value in a rotated sorted array of distinct integers.

    Args:
    nums (list): A rotated sorted array of integers.
    target (int): The target integer to be searched.

    Returns:
    int: The index of the target if found; -1 otherwise.
    """
    if not nums:
        return -1  # Edge case: empty array

    left, right = 0, len(nums) - 1  # Initialize pointers for binary search

    while left <= right:
        mid = (left + right) // 2  # Calculate mid index

        if nums[mid] == target:
            return mid  # Target found, return its index

        # Check if left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                # Target is in the left half, update right pointer
                right = mid - 1
            else:
                # Target is in the right half, update left pointer
                left = mid + 1
        else:
            # Left half is not sorted, right half must be sorted
            if nums[mid] < target <= nums[right]:
                # Target is in the right half, update left pointer
                left = mid + 1
            else:
                # Target is in the left half, update right pointer
                right = mid - 1

    return -1  # Target not found

def solution(nums, target):
    """
    Searches for a target value in a rotated sorted array.

    Args:
    nums (list): A rotated sorted array of unique integers.
    target (int): The target value to search for.

    Returns:
    int: The index of the target value if found, -1 otherwise.
    """
    if not nums:
        return -1  # Edge case: empty array

    left, right = 0, len(nums) - 1  # Initialize search boundaries

    while left <= right:
        mid = (left + right) // 2  # Calculate mid index

        if nums[mid] == target:
            return mid  # Target found, return its index

        # Determine which half is sorted
        if nums[left] <= nums[mid]:
            # Left half is sorted
            if nums[left] <= target < nums[mid]:
                # Target is in the sorted left half
                right = mid - 1  # Update right boundary
            else:
                left = mid + 1  # Target is in the right half
        else:
            # Right half is sorted
            if nums[mid] < target <= nums[right]:
                # Target is in the sorted right half
                left = mid + 1  # Update left boundary
            else:
                right = mid - 1  # Target is in the left half

    return -1  # Target not found

