def solution(strings):
    def get_char_frequency(s):
        freq = {}
        for char in s.lower():
            if char in freq:
                freq[char] += 1
            else:
                freq[char] = 1
        return tuple(sorted(freq.items()))

    def recursive_sort(strings):
        if len(strings) <= 1:
            return strings
        pivot = strings[0]
        less = [x for x in strings[1:] if (get_char_frequency(x), x) < (get_char_frequency(pivot), pivot)]
        equal = [x for x in strings[1:] if (get_char_frequency(x), x) == (get_char_frequency(pivot), pivot)]
        greater = [x for x in strings[1:] if (get_char_frequency(x), x) > (get_char_frequency(pivot), pivot)]
        return recursive_sort(less) + [pivot] + equal + recursive_sort(greater)

    return recursive_sort(strings)

def solution(nums):
    """
    This function calculates the maximum sum of non-adjacent items in an array.
    Before calculating the sum, the array is sorted in non-decreasing order.

    Args:
        nums (list): A list of integers representing the values of items.

    Returns:
        int: The maximum sum of non-adjacent items after sorting the array.
    """

    # Handle edge cases
    if not nums:
        return 0
    if len(nums) <= 2:
        return max(0, max(nums))

    # Sort the array in non-decreasing order
    nums.sort()

    # If the array has an odd length, consider including or excluding the middle element
    n = len(nums)
    if n % 2 == 1:
        return max(nums[-1] + sum(nums[0:-1:2]), nums[-2] + sum(nums[1:-1:2]))
    else:
        sum_start = sum(nums[::2])
        sum_end = sum(nums[1::2])
        return max(sum_start, sum_end)

def solution(nums):
    if not nums:
        return 0
    if len(nums) <= 2:
        return max(nums)

    nums.sort()
    n = len(nums)
    dp = [0] * n
    dp[0] = nums[0]
    dp[1] = max(nums[0], nums[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i])

    return dp[-1]

