def solution(a, b):
    # Base case: if b is zero, return 0
    if b == 0:
        return 0

    # If b is negative, convert to positive and make a negative
    if b < 0:
        return -solution(a, -b)

    # Recursive case: add a to the result of a multiplied by (b-1)
    return a + solution(a, b-1)

