def solution(a, b):
    # Base case: if b is zero, return 0
    if b == 0:
        return 0

    # If b is negative, convert to positive and make a negative
    if b < 0:
        return -solution(a, -b)

    # If b is even
    if b % 2 == 0:
        half_product = solution(a, b // 2)
        return half_product + half_product
    # If b is odd
    else:
        half_product = solution(a, (b - 1) // 2)
        return a + half_product + half_product

